\label{thm:main}
For oriented tame knots $K,\,L\,\subset\, S^3$, the following three statements are
equivalent:
\begin{enumerate}
\item $K\ \simeq\ L$;

\item $\mathcal W(K)\ \cong\ \mathcal W(L)$;

\item $\mathcal P(K)\ \cong\ \mathcal P(L)$.
\end{enumerate}

\label{cor:colouring-main}
For oriented tame knots $K,\,L$, the following are equivalent:
\begin{enumerate}
\item $K\,\simeq\, L$;
\item $\mathcal Q_w(K)\,=\,\mathcal Q_w(L)$;
\item $N_Q(z;K)\,=\,N_Q(z;L)$ for every finite $Q$ and $z\,\in\, Q$;
\item $\mathcal Q(K)\,=\,\mathcal Q(L)$;
\item $P_Q^x(K)\,=\,P_Q^x(L)$ for every finite $Q$ and $x\,\in\, Q$.
\end{enumerate}

\label{prop:finite}
For topologically finitely generated profinite groups $(P,\,\mathbf a)$
and $(R,\,\mathbf c)$ with the same number of marks, the following three
statements are equivalent:
\begin{enumerate}
\item There is a continuous isomorphism $P\, \longrightarrow\, R$ taking
$\mathbf a$ to $\mathbf c$;

\item $\mathcal Q(P,\,\mathbf a)\,=\,\mathcal Q(R,\,\mathbf c)$;

\item $H_P(Q;\,\mathbf x)\,=\,H_R(Q;\,\mathbf x)$ for every finite $Q$ and ordered string
$\mathbf x$.
\end{enumerate}

\label{lem:fibre-slope}
For a nontrivial prime knot with Seifert root, a regular fibre on the
exterior boundary, oriented to follow the knot positively, has elements
\begin{equation}\label{eq:prime-fibre}
 h_K\ =\ \mu_K^{c_K}\lambda_K,\quad c_K\ \in\ \mathbb Z,\quad |c_K|\ \ge\ 2.
\end{equation}
Its closure is characteristic in the root completion and is a copy of
$\widehat{\mathbb Z}$.

\label{thm:hyp-integral-regular}
For any continuous isomorphism between completions of cusped hyperbolic
piece groups, every normalized cusp map belongs to $\operatorname{GL}_2(\mathbb Z)$.
